script:
frappe.call({method: "stockist_dashboard_stats"}).then(r => {
	const d = r.message || {};
	const fmt = n => "₹" + Math.round(n).toLocaleString("en-IN");
	root_element.getElementById("sk-new-orders").textContent = d.new_orders ?? "--";
	root_element.getElementById("sk-today-sales").textContent = fmt(d.today_sales || 0);
	root_element.getElementById("sk-total-dues").textContent = fmt(d.total_dues || 0);
	root_element.getElementById("sk-active-customers").textContent = d.active_customers ?? "--";
	root_element.getElementById("sk-total-customers").textContent = "of " + (d.total_customers ?? "--") + " total";
});

(function () {
	let DATA = { active: [], not_onboarded: [], needs_review: [] };
	let TAB = "active";

	const fmt = n => "₹" + Math.round(n || 0).toLocaleString("en-IN");
	const tbody = root_element.getElementById("sk-cust-tbody");
	const thead = root_element.getElementById("sk-cust-thead");
	const empty = root_element.getElementById("sk-cust-empty");
	const search = root_element.getElementById("sk-cust-search");

	function showPin(mobile, pin) {
		root_element.getElementById("sk-pin-mobile").textContent = mobile;
		root_element.getElementById("sk-pin-value").textContent = pin;
		root_element.getElementById("sk-pin-modal").style.display = "flex";
	}
	root_element.getElementById("sk-pin-close").onclick = () => {
		root_element.getElementById("sk-pin-modal").style.display = "none";
		load();
	};

	function btn(label, color) {
		return `<button class="sk-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;margin-right:4px;">${label}</button>`;
	}

	function render() {
		const rows = DATA[TAB] || [];
		const q = (search.value || "").toLowerCase().trim();
		const filtered = q
			? rows.filter(r => (r.customer_name || "").toLowerCase().includes(q) || (r.mobile_no || "").includes(q))
			: rows;

		root_element.querySelectorAll(".sk-tab-btn").forEach(b => {
			const active = b.dataset.tab === TAB;
			b.style.background = active ? "#3E2417" : "#fff";
			b.style.color = active ? "#fff" : "#3E2417";
		});

		if (TAB === "active") {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='text-align:left;padding:8px;'>Due</th><th style='text-align:left;padding:8px;'>Status</th><th style='padding:8px;'>Actions</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no || "-"}</td>
					<td style="padding:8px;">${fmt(r.due)}</td>
					<td style="padding:8px;">${r.status === "active" ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Revoked</span>"}</td>
					<td style="padding:8px;white-space:nowrap;">
						${btn("Reset PIN", "#3E2417")}
						${r.status === "active" ? btn("Revoke", "#c33") : btn("Restore", "#2a8")}
					</td>
				</tr>`).join("");
			tbody.querySelectorAll("tr").forEach((tr, i) => {
				const r = filtered[i];
				const [resetBtn, toggleBtn] = tr.querySelectorAll(".sk-act");
				resetBtn.onclick = () => frappe.call({ method: "stockist_reset_pin", args: { customer: r.customer } })
					.then(res => showPin(res.message.mobile_no, res.message.pin));
				toggleBtn.onclick = () => frappe.call({ method: "stockist_toggle_access", args: { customer: r.customer, enable: r.status === "active" ? 0 : 1 } })
					.then(() => load());
			});
		} else if (TAB === "not_onboarded") {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='padding:8px;'>Actions</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no ? r.mobile_no : "<input type='tel' class='sk-mobile-input' placeholder='Enter mobile number' style='padding:4px;border:1px solid #ccc;border-radius:4px;width:130px;'>"}</td>
					<td style="padding:8px;">${btn("Grant Access", "#3E2417")}</td>
				</tr>`).join("");
			tbody.querySelectorAll("tr").forEach((tr, i) => {
				const r = filtered[i];
				const grantBtn = tr.querySelector(".sk-act");
				const input = tr.querySelector(".sk-mobile-input");
				grantBtn.onclick = () => {
					const mobile = r.mobile_no || (input && input.value.trim());
					if (!mobile) { frappe.msgprint("Enter a mobile number first."); return; }
					frappe.call({ method: "stockist_grant_access", args: { customer: r.customer, mobile_no: mobile } })
						.then(res => showPin(res.message.mobile_no, res.message.pin));
				};
			});
		} else {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='text-align:left;padding:8px;'>Due</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no || "-"}</td>
					<td style="padding:8px;">${fmt(r.due)}</td>
				</tr>`).join("");
		}
		empty.style.display = filtered.length ? "none" : "block";
		root_element.getElementById("sk-cust-table-wrap").style.display = filtered.length ? "block" : "none";
	}

	function load() {
		frappe.call({ method: "stockist_customer_access_list" }).then(r => {
			DATA = r.message || DATA;
			render();
		});
	}

	root_element.querySelectorAll(".sk-tab-btn").forEach(b => {
		b.onclick = () => { TAB = b.dataset.tab; render(); };
	});
	search.oninput = render;

	load();
})();

const btn = root_element.getElementById("sk-sync-btn");
const status = document.createElement("div");
status.id = "sk-sync-status";
status.style.cssText = "font-size:12px;color:#888;margin-top:6px;";
btn.parentElement.parentElement.appendChild(status);

frappe.realtime.on("kirana_console_sync_done", (r) => {
	btn.disabled = false;
	btn.textContent = "Sync Now";
	if (r.status === "success") {
		status.style.color = "#2a8";
		status.textContent = r.summary;
	} else {
		status.style.color = "#c33";
		status.textContent = "Sync failed: " + r.message;
	}
});

btn.onclick = () => {
	btn.disabled = true;
	btn.textContent = "Syncing...";
	status.style.color = "#888";
	status.textContent = "This can take a couple of minutes for a full catalog.";
	frappe.call({ method: "kirana_console.sync.sync_now" }).catch(() => {
		btn.disabled = false;
		btn.textContent = "Sync Now";
	});
};

(function () {
	let ITEMS = [];
	let EDITING = null;

	const tbody = root_element.getElementById("sk-prod-tbody");
	const empty = root_element.getElementById("sk-prod-empty");
	const search = root_element.getElementById("sk-prod-search");
	const modal = root_element.getElementById("sk-prod-modal");
	const fmt = n => "₹" + Math.round(n || 0).toLocaleString("en-IN");

	function openModal(item) {
		EDITING = item;
		root_element.getElementById("sk-prod-edit-name").value = item.item_name || "";
		root_element.getElementById("sk-prod-edit-price").value = item.price || 0;
		root_element.getElementById("sk-prod-edit-group").value = item.item_group || "";
		modal.style.display = "flex";
	}
	root_element.getElementById("sk-prod-cancel").onclick = () => { modal.style.display = "none"; };
	root_element.getElementById("sk-prod-save").onclick = () => {
		const name = root_element.getElementById("sk-prod-edit-name").value.trim();
		const price = parseFloat(root_element.getElementById("sk-prod-edit-price").value);
		const group = root_element.getElementById("sk-prod-edit-group").value.trim();
		frappe.call({
			method: "stockist_update_product",
			args: { item_code: EDITING.item_code, item_name: name, price: price, item_group: group },
		}).then(() => {
			modal.style.display = "none";
			load();
		});
	};

	function btn(label, color) {
		return `<button class="sk-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;margin-right:4px;">${label}</button>`;
	}

	function render() {
		const q = (search.value || "").toLowerCase().trim();
		const filtered = q
			? ITEMS.filter(r => (r.item_name || "").toLowerCase().includes(q) || (r.brand || "").toLowerCase().includes(q))
			: ITEMS;

		tbody.innerHTML = filtered.slice(0, 200).map(r => `
			<tr style="border-top:1px solid #eee;">
				<td style="padding:8px;">${r.item_name}${r.overridden ? " <span style='color:#EE8B1D;font-size:11px;'>(edited)</span>" : ""}</td>
				<td style="padding:8px;">${r.item_group}</td>
				<td style="padding:8px;">${fmt(r.price)}</td>
				<td style="padding:8px;">${r.active ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Inactive</span>"}</td>
				<td style="padding:8px;white-space:nowrap;">
					${btn("Edit", "#3E2417")}
					${r.active ? btn("Deactivate", "#c33") : btn("Activate", "#2a8")}
				</td>
			</tr>`).join("");

		tbody.querySelectorAll("tr").forEach((tr, i) => {
			const r = filtered[i];
			const [editBtn, toggleBtn] = tr.querySelectorAll(".sk-act");
			editBtn.onclick = () => openModal(r);
			toggleBtn.onclick = () => frappe.call({
				method: "stockist_update_product",
				args: { item_code: r.item_code, active: r.active ? 0 : 1 },
			}).then(() => load());
		});

		empty.style.display = filtered.length ? "none" : "block";
		root_element.getElementById("sk-prod-table-wrap").style.display = filtered.length ? "block" : "none";
		if (filtered.length > 200) {
			const note = document.createElement("tr");
			note.innerHTML = `<td colspan="5" style="padding:8px;text-align:center;color:#999;font-size:12px;">Showing first 200 of ${filtered.length} - narrow your search to see more.</td>`;
			tbody.appendChild(note);
		}
	}

	function load() {
		frappe.call({ method: "stockist_products_list" }).then(r => {
			ITEMS = (r.message && r.message.items) || [];
			render();
		});
	}

	search.oninput = render;
	load();
})();

(function () {
	// ---- tabs ----
	root_element.querySelectorAll(".sk-mkt-tab").forEach(function (b) {
		b.onclick = function () {
			root_element.querySelectorAll(".sk-mkt-tab").forEach(function (x) {
				x.style.background = "#fff"; x.style.color = "#3E2417";
			});
			b.style.background = "#3E2417"; b.style.color = "#fff";
			root_element.getElementById("sk-mkt-announcements").style.display = b.dataset.tab === "announcements" ? "block" : "none";
			root_element.getElementById("sk-mkt-coupons").style.display = b.dataset.tab === "coupons" ? "block" : "none";
			root_element.getElementById("sk-mkt-offers").style.display = b.dataset.tab === "offers" ? "block" : "none";
		};
	});

	// ---- announcements ----
	function annBtn(label, color) {
		return `<button class="sk-ann-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;">${label}</button>`;
	}
	function loadAnnouncements() {
		frappe.call({ method: "stockist_announcements_list" }).then(function (r) {
			var rows = (r.message && r.message.announcements) || [];
			var tbody = root_element.getElementById("sk-ann-tbody");
			tbody.innerHTML = rows.map(function (a) {
				return `<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${a.title}</td>
					<td style="padding:8px;">${a.announcement_type}</td>
					<td style="padding:8px;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${a.message}</td>
					<td style="padding:8px;">${a.is_active ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Off</span>"}</td>
					<td style="padding:8px;">${annBtn(a.is_active ? "Turn Off" : "Turn On", a.is_active ? "#c33" : "#2a8")}</td>
				</tr>`;
			}).join("");
			tbody.querySelectorAll("tr").forEach(function (tr, i) {
				var a = rows[i];
				tr.querySelector(".sk-ann-act").onclick = function () {
					frappe.call({ method: "stockist_toggle_announcement", args: { name: a.name, enable: a.is_active ? 0 : 1 } }).then(loadAnnouncements);
				};
			});
		});
	}
	root_element.getElementById("sk-ann-new").onclick = function () {
		root_element.getElementById("sk-ann-title").value = "";
		root_element.getElementById("sk-ann-message").value = "";
		root_element.getElementById("sk-ann-end").value = "";
		root_element.getElementById("sk-ann-modal").style.display = "flex";
	};
	root_element.getElementById("sk-ann-cancel").onclick = function () {
		root_element.getElementById("sk-ann-modal").style.display = "none";
	};
	root_element.getElementById("sk-ann-save").onclick = function () {
		var title = root_element.getElementById("sk-ann-title").value.trim();
		var type = root_element.getElementById("sk-ann-type").value;
		var message = root_element.getElementById("sk-ann-message").value.trim();
		var end = root_element.getElementById("sk-ann-end").value;
		if (!title || !message) { frappe.msgprint("Title and message are required."); return; }
		frappe.call({
			method: "stockist_create_announcement",
			args: { title: title, announcement_type: type, message: message, end_date: end || null },
		}).then(function () {
			root_element.getElementById("sk-ann-modal").style.display = "none";
			loadAnnouncements();
		});
	};

	// ---- coupons ----
	function couponBtn(label, color) {
		return `<button class="sk-coupon-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;">${label}</button>`;
	}
	function loadCoupons() {
		frappe.call({ method: "stockist_coupons_list" }).then(function (r) {
			var rows = (r.message && r.message.coupons) || [];
			var tbody = root_element.getElementById("sk-coupon-tbody");
			tbody.innerHTML = rows.map(function (c) {
				return `<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;font-weight:600;">${c.code}</td>
					<td style="padding:8px;">${c.discount}</td>
					<td style="padding:8px;">${c.used}${c.max_use ? " / " + c.max_use : ""}</td>
					<td style="padding:8px;">${c.active ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Off</span>"}</td>
					<td style="padding:8px;">${couponBtn(c.active ? "Turn Off" : "Turn On", c.active ? "#c33" : "#2a8")}</td>
				</tr>`;
			}).join("");
			tbody.querySelectorAll("tr").forEach(function (tr, i) {
				var c = rows[i];
				tr.querySelector(".sk-coupon-act").onclick = function () {
					frappe.call({ method: "stockist_toggle_coupon", args: { name: c.name, enable: c.active ? 0 : 1 } }).then(loadCoupons);
				};
			});
		});
	}
	root_element.getElementById("sk-coupon-new").onclick = function () {
		root_element.getElementById("sk-coupon-code").value = "";
		root_element.getElementById("sk-coupon-value").value = "";
		root_element.getElementById("sk-coupon-max").value = "0";
		root_element.getElementById("sk-coupon-modal").style.display = "flex";
	};
	root_element.getElementById("sk-coupon-cancel").onclick = function () {
		root_element.getElementById("sk-coupon-modal").style.display = "none";
	};
	root_element.getElementById("sk-coupon-save").onclick = function () {
		var code = root_element.getElementById("sk-coupon-code").value.trim().toUpperCase();
		var type = root_element.getElementById("sk-coupon-type").value;
		var value = root_element.getElementById("sk-coupon-value").value;
		var max = root_element.getElementById("sk-coupon-max").value;
		if (!code || !value) { frappe.msgprint("Code and discount value are required."); return; }
		frappe.call({
			method: "stockist_create_coupon",
			args: { code: code, discount_type: type, discount_value: value, max_use: max },
		}).then(function () {
			root_element.getElementById("sk-coupon-modal").style.display = "none";
			loadCoupons();
		});
	};

	// ---- spend & save offers ----
	var offerCustomers = []; // [{customer, customer_name}]
	var offerEditingName = null;

	function offerBtn(label, color) {
		return `<button class="sk-offer-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;margin-right:4px;">${label}</button>`;
	}

	function loadOffers() {
		frappe.call({ method: "stockist_offers_list" }).then(function (r) {
			var rows = r.message || [];
			var tbody = root_element.getElementById("sk-offer-tbody");
			tbody.innerHTML = rows.map(function (o) {
				return `<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;font-weight:600;">${o.offer_name}</td>
					<td style="padding:8px;">${o.audience}</td>
					<td style="padding:8px;max-width:220px;font-size:12px;color:#666;">${o.tiers_summary}</td>
					<td style="padding:8px;">${o.active ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Off</span>"}</td>
					<td style="padding:8px;white-space:nowrap;">
						${offerBtn("Edit", "#3E2417")}
						${offerBtn(o.active ? "Turn Off" : "Turn On", o.active ? "#c33" : "#2a8")}
					</td>
				</tr>`;
			}).join("");
			tbody.querySelectorAll("tr").forEach(function (tr, i) {
				var o = rows[i];
				var acts = tr.querySelectorAll(".sk-offer-act");
				acts[0].onclick = function () { openOfferModal(o.name); };
				acts[1].onclick = function () {
					frappe.call({ method: "stockist_offer_toggle", args: { name: o.name, enable: o.active ? 0 : 1 } }).then(loadOffers);
				};
			});
		});
	}

	function addTierRow(active, minAmount, discountPct) {
		var wrap = root_element.getElementById("sk-offer-tiers");
		var row = document.createElement("div");
		row.className = "sk-offer-tier-row";
		row.style.cssText = "display:flex;gap:6px;align-items:center;margin-bottom:6px;";
		row.innerHTML =
			'<input type="checkbox" class="sk-tier-active" style="flex:none;" ' + (active === false ? "" : "checked") + '>' +
			'<span style="font-size:12px;color:#888;flex:none;">Spend Rs</span>' +
			'<input type="number" class="sk-tier-amount" placeholder="1000" value="' + (minAmount != null ? minAmount : "") + '" style="width:80px;padding:6px;border:1px solid #ccc;border-radius:6px;">' +
			'<span style="font-size:12px;color:#888;flex:none;">get</span>' +
			'<input type="number" class="sk-tier-pct" placeholder="10" value="' + (discountPct != null ? discountPct : "") + '" style="width:60px;padding:6px;border:1px solid #ccc;border-radius:6px;">' +
			'<span style="font-size:12px;color:#888;flex:none;">% off</span>' +
			'<button type="button" class="sk-tier-remove" style="margin-left:auto;border:none;background:none;color:#c33;cursor:pointer;font-size:16px;line-height:1;">&times;</button>';
		row.querySelector(".sk-tier-remove").onclick = function () { row.remove(); };
		wrap.appendChild(row);
	}

	function resetOfferModal() {
		offerEditingName = null;
		offerCustomers = [];
		root_element.getElementById("sk-offer-modal-title").textContent = "New Spend & Save Offer";
		root_element.getElementById("sk-offer-name").value = "";
		root_element.getElementById("sk-offer-audience").value = "All Customers";
		root_element.getElementById("sk-offer-customers-wrap").style.display = "none";
		root_element.getElementById("sk-offer-customer-search").value = "";
		root_element.getElementById("sk-offer-customer-results").innerHTML = "";
		renderCustomerChips();
		root_element.getElementById("sk-offer-tiers").innerHTML = "";
		addTierRow(true, null, null);
	}

	function renderCustomerChips() {
		var wrap = root_element.getElementById("sk-offer-customer-chips");
		wrap.innerHTML = offerCustomers.map(function (c, i) {
			return '<span style="background:#f2e9e0;color:#3E2417;padding:4px 8px;border-radius:999px;font-size:12px;display:inline-flex;align-items:center;gap:4px;">' +
				c.customer_name + '<span data-i="' + i + '" class="sk-chip-remove" style="cursor:pointer;font-weight:700;">&times;</span></span>';
		}).join("");
		wrap.querySelectorAll(".sk-chip-remove").forEach(function (el) {
			el.onclick = function () {
				offerCustomers.splice(parseInt(el.dataset.i, 10), 1);
				renderCustomerChips();
			};
		});
	}

	function openOfferModal(name) {
		resetOfferModal();
		if (name) {
			frappe.call({ method: "stockist_offer_get", args: { name: name } }).then(function (r) {
				var d = r.message;
				offerEditingName = d.name;
				root_element.getElementById("sk-offer-modal-title").textContent = "Edit Offer";
				root_element.getElementById("sk-offer-name").value = d.offer_name;
				root_element.getElementById("sk-offer-audience").value = d.audience;
				root_element.getElementById("sk-offer-customers-wrap").style.display = d.audience === "Selected Customers" ? "block" : "none";
				offerCustomers = d.customers || [];
				renderCustomerChips();
				root_element.getElementById("sk-offer-tiers").innerHTML = "";
				(d.tiers || []).forEach(function (t) {
					addTierRow(!!t.active, t.min_amount, t.discount_percentage);
				});
				if (!d.tiers || !d.tiers.length) addTierRow(true, null, null);
				root_element.getElementById("sk-offer-modal").style.display = "flex";
			});
		} else {
			root_element.getElementById("sk-offer-modal").style.display = "flex";
		}
	}

	root_element.getElementById("sk-offer-new").onclick = function () { openOfferModal(null); };
	root_element.getElementById("sk-offer-cancel").onclick = function () {
		root_element.getElementById("sk-offer-modal").style.display = "none";
	};
	root_element.getElementById("sk-offer-add-tier").onclick = function () { addTierRow(true, null, null); };
	root_element.getElementById("sk-offer-audience").onchange = function () {
		root_element.getElementById("sk-offer-customers-wrap").style.display = this.value === "Selected Customers" ? "block" : "none";
	};

	var customerSearchTimer = null;
	root_element.getElementById("sk-offer-customer-search").oninput = function () {
		var q = this.value.trim();
		clearTimeout(customerSearchTimer);
		var resultsEl = root_element.getElementById("sk-offer-customer-results");
		if (q.length < 2) { resultsEl.innerHTML = ""; return; }
		customerSearchTimer = setTimeout(function () {
			frappe.call({ method: "stockist_search_customers", args: { query: q } }).then(function (r) {
				var rows = r.message || [];
				resultsEl.innerHTML = rows.map(function (c) {
					return '<div class="sk-customer-result" data-customer="' + c.customer + '" data-name="' + c.customer_name + '" style="padding:6px 8px;font-size:13px;cursor:pointer;border-bottom:1px solid #f5f5f5;">' + c.customer_name + '</div>';
				}).join("");
				resultsEl.querySelectorAll(".sk-customer-result").forEach(function (el) {
					el.onclick = function () {
						var customer = el.dataset.customer;
						if (!offerCustomers.some(function (c) { return c.customer === customer; })) {
							offerCustomers.push({ customer: customer, customer_name: el.dataset.name });
							renderCustomerChips();
						}
						resultsEl.innerHTML = "";
						root_element.getElementById("sk-offer-customer-search").value = "";
					};
				});
			});
		}, 250);
	};

	root_element.getElementById("sk-offer-save").onclick = function () {
		var offerName = root_element.getElementById("sk-offer-name").value.trim();
		var audience = root_element.getElementById("sk-offer-audience").value;
		if (!offerName) { frappe.msgprint("Offer name is required."); return; }
		if (audience === "Selected Customers" && !offerCustomers.length) {
			frappe.msgprint("Add at least one customer, or switch to All Customers.");
			return;
		}
		var tierRows = root_element.querySelectorAll(".sk-offer-tier-row");
		var tiers = [];
		var invalid = false;
		tierRows.forEach(function (row) {
			var amount = row.querySelector(".sk-tier-amount").value;
			var pct = row.querySelector(".sk-tier-pct").value;
			if (!amount || !pct) { invalid = true; return; }
			tiers.push({
				active: row.querySelector(".sk-tier-active").checked,
				min_amount: parseFloat(amount),
				discount_percentage: parseFloat(pct),
			});
		});
		if (invalid || !tiers.length) {
			frappe.msgprint("Fill in the amount and discount for every tier, or remove empty ones.");
			return;
		}
		frappe.call({
			method: "stockist_offer_save",
			args: {
				name: offerEditingName,
				offer_name: offerName,
				audience: audience,
				customers: JSON.stringify(offerCustomers),
				tiers: JSON.stringify(tiers),
			},
		}).then(function () {
			root_element.getElementById("sk-offer-modal").style.display = "none";
			loadOffers();
		});
	};

	loadAnnouncements();
	loadCoupons();
	loadOffers();
})();

(function () {
	let ORDERS = [];
	let TAB = "all";
	let CURRENT_DETAIL = null;

	const fmt = n => "₹" + Math.round(n || 0).toLocaleString("en-IN");
	const list = root_element.getElementById("sk-ord-list");
	const empty = root_element.getElementById("sk-ord-empty");
	const search = root_element.getElementById("sk-ord-search");
	const modal = root_element.getElementById("sk-ord-detail-modal");

	function statusPill(status) {
		let color = "#999", bg = "#f2f2f2";
		if (status === "To Deliver and Bill" || status === "To Deliver" || status === "To Bill") {
			color = "#c77c1a"; bg = "#fdf1e0";
		} else if (status === "Closed" || status === "Completed") {
			color = "#2a8"; bg = "#e5f6ea";
		} else if (status === "Cancelled") {
			color = "#c33"; bg = "#fbe7e5";
		}
		return "<span style='display:inline-block;padding:3px 10px;border-radius:999px;font-size:12px;font-weight:600;color:" + color + ";background:" + bg + ";'>" + status + "</span>";
	}

	function render() {
		const q = (search.value || "").toLowerCase().trim();
		let rows = ORDERS;
		if (TAB !== "all") {
			if (TAB === "Closed") {
				rows = rows.filter(r => r.status === "Closed" || r.status === "Completed");
			} else {
				rows = rows.filter(r => r.status !== "Closed" && r.status !== "Completed" && r.status !== "Cancelled");
			}
		}
		if (q) {
			rows = rows.filter(r =>
				(r.customer_name || "").toLowerCase().includes(q) ||
				(r.name || "").toLowerCase().includes(q)
			);
		}

		root_element.querySelectorAll(".sk-ord-tab").forEach(b => {
			const active = b.dataset.status === TAB;
			b.style.background = active ? "#3E2417" : "#fff";
			b.style.color = active ? "#fff" : "#3E2417";
		});

		empty.style.display = rows.length ? "none" : "block";
		list.innerHTML = rows.map(r =>
			"<div class='sk-ord-row' data-name='" + r.name + "' style='padding:14px;border:1px solid #eee;border-radius:8px;margin-bottom:8px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:12px;'>" +
				"<div style='min-width:0;'>" +
					"<div style='font-weight:600;color:#241710;'>" + r.customer_name + "</div>" +
					"<div style='font-size:13px;color:#888;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;'>" + r.item_summary + "</div>" +
					"<div style='font-size:12px;color:#aaa;margin-top:4px;'>" + r.name + " &middot; " + (r.transaction_date || "") + "</div>" +
				"</div>" +
				"<div style='text-align:right;flex:none;'>" +
					"<div style='font-weight:700;margin-bottom:6px;'>" + fmt(r.grand_total) + "</div>" +
					statusPill(r.status) +
				"</div>" +
			"</div>"
		).join("");

		list.querySelectorAll(".sk-ord-row").forEach(row => {
			row.onclick = () => openDetail(row.dataset.name);
		});
	}

	function openDetail(name) {
		frappe.call({ method: "stockist_order_detail", args: { name: name } }).then(res => {
			const d = res.message;
			CURRENT_DETAIL = d;
			root_element.getElementById("sk-ord-detail-name").textContent = d.name;
			root_element.getElementById("sk-ord-detail-customer").textContent = d.customer_name + (d.contact_mobile ? " · " + d.contact_mobile : "");
			const metaParts = [];
			if (d.transaction_date) metaParts.push("Ordered: " + d.transaction_date);
			if (d.address) metaParts.push(d.address);
			metaParts.push(statusPill(d.status));
			root_element.getElementById("sk-ord-detail-meta").innerHTML = metaParts.join(" &middot; ");
			root_element.getElementById("sk-ord-detail-items").innerHTML = d.items.map(i =>
				"<tr style='border-bottom:1px solid #f5f5f5;'>" +
					"<td style='padding:6px 4px;'>" + i.item_name + "</td>" +
					"<td style='padding:6px 4px;text-align:center;'>" + i.qty + "</td>" +
					"<td style='padding:6px 4px;text-align:right;'>" + fmt(i.amount) + "</td>" +
				"</tr>"
			).join("");
			root_element.getElementById("sk-ord-detail-total").textContent = fmt(d.grand_total);

			const completeBtn = root_element.getElementById("sk-ord-detail-complete");
			const isDone = d.status === "Closed" || d.status === "Completed" || d.status === "Cancelled";
			completeBtn.style.display = isDone ? "none" : "block";

			modal.style.display = "flex";
		});
	}

	root_element.getElementById("sk-ord-detail-close").onclick = () => {
		modal.style.display = "none";
	};
	root_element.getElementById("sk-ord-detail-complete").onclick = function () {
		if (!CURRENT_DETAIL) return;
		const btn = this;
		btn.textContent = "Updating...";
		frappe.call({ method: "stockist_order_complete", args: { name: CURRENT_DETAIL.name } })
			.then(() => {
				modal.style.display = "none";
				btn.textContent = "Mark as Completed";
				load();
			})
			.catch(() => {
				btn.textContent = "Mark as Completed";
				frappe.msgprint("Could not update the order. Please try again.");
			});
	};

	root_element.querySelectorAll(".sk-ord-tab").forEach(b => {
		b.onclick = () => { TAB = b.dataset.status; render(); };
	});
	search.oninput = render;

	function load() {
		frappe.call({ method: "stockist_order_list" }).then(r => {
			ORDERS = r.message || [];
			render();
		});
	}

	load();
})();
